"""Build visual agent review notebook for selected source train examples."""
import nbformat as nb

b = nb.v4.new_notebook()
md, code = nb.v4.new_markdown_cell, nb.v4.new_code_cell
b.cells = [
    md('# 16.10 - Visual target annotation pilot\n\nManually inspect original-resolution images selected from the source train split. The occlusal checkpoint scores were used only to prioritize review. These are provisional visual research annotations by Codex, not orthodontist diagnoses or an independent validation set.'),
    code('from pathlib import Path\nimport hashlib\nimport pandas as pd\nimport matplotlib.pyplot as plt\nfrom PIL import Image, ImageDraw\nfrom IPython.display import display\nroot=Path.cwd().resolve()\nwhile not (root / "AGENTS.md").exists():\n    if root==root.parent: raise RuntimeError("Project root not found")\n    root=root.parent\nbase=root / "data/processed/alignment_omni_frontal_candidates"\nqueue=pd.read_csv(base / "review_queue.csv",dtype={"source_image_id":str,"sha256":str}).set_index("source_image_id")\nexcluded=set(pd.read_csv(root / "docs/reports/alignment/omni_frontal_candidate_audit/conservative_train_exclusions.csv",dtype=str).source_image_id)\nprint("Source train candidates:",sum(queue.split=="train"),"| conservative exclusions:",len(excluded))'),
    md('## 1. Record visible targets with explicit box coordinates\n\nA midline gap box surrounds both upper central incisors. A crowding box includes the displaced anterior tooth and adjacent teeth. Borderline findings are omitted from this initial positive pilot. An omitted target has unknown status, never an assumed negative.'),
    code('proposals = pd.DataFrame([\n    ("201916202112081", "upper_midline_diastema", 174, 90, 326, 190, "visible central separation"),\n    ("202139202205251", "upper_midline_diastema", 183, 120, 337, 195, "visible central separation"),\n    ("202212202202071", "upper_midline_diastema", 173, 122, 303, 185, "visible central separation"),\n    ("202362202308141", "upper_midline_diastema", 173, 128, 335, 205, "visible central separation"),\n    ("202244202207131", "anterior_crowding", 255, 85, 425, 190, "visible anterior displacement and overlap"),\n], columns=["source_image_id","target","x_min","y_min","x_max","y_max","visual_reason"])\nproposals["reviewer"]="Codex visual review"\nproposals["review_state"]="agent_visual_provisional"\nfor row in proposals.itertuples():\n    source=queue.loc[row.source_image_id]\n    assert source["split"]=="train" and row.source_image_id not in excluded\n    assert 0<=row.x_min<row.x_max<=int(source["width"]) and 0<=row.y_min<row.y_max<=int(source["height"])\n    image=root / source["image_path"]\n    assert hashlib.sha256(image.read_bytes()).hexdigest()==source["sha256"]\nprint("Checked visual proposals:",len(proposals))\ndisplay(proposals)'),
    md('## 2. Verify overlays\n\nReview each proposed box on the original image. This visual QA checks coordinates; it does not turn the annotation into a clinical ground truth.'),
    code('fig, axes=plt.subplots(3,2,figsize=(12,12))\nfor ax,row in zip(axes.flat,proposals.itertuples()):\n    image=Image.open(root / queue.loc[row.source_image_id,"image_path"])\n    ax.imshow(image)\n    ax.add_patch(plt.Rectangle((row.x_min,row.y_min),row.x_max-row.x_min,row.y_max-row.y_min,fill=False,edgecolor="lime",linewidth=2))\n    ax.set_title(f"{row.source_image_id}: {row.target}")\n    ax.axis("off")\nfor ax in list(axes.flat)[len(proposals):]: ax.axis("off")\nfig.tight_layout()\nout=root / "docs/reports/alignment/agent_visual_pilot"\nout.mkdir(parents=True,exist_ok=True)\nfig.savefig(out / "provisional_boxes.png",dpi=140)\nplt.show()\nplt.close(fig)'),
    md('## 3. Save provisional evidence\n\nStore this separate from the approved review queue. It can seed exploratory training after the annotation protocol and class coverage are reviewed; it is not ready for final accuracy claims.'),
    code('path=out / "agent_visual_proposals.csv"\nif path.exists():\n    old=pd.read_csv(path,dtype={"source_image_id":str})\n    assert old.equals(proposals), "Existing proposals differ; review rather than overwrite"\nelse: proposals.to_csv(path,index=False)\nprint("Saved:",path)\nprint("Visual positives per target:")\ndisplay(proposals.groupby("target").size().to_frame("provisional_boxes"))'),
]
b.metadata.kernelspec={'display_name':'DentalSelfie','language':'python','name':'dentalselfie-local'}
nb.write(b,'notebooks/alignment/16_10_agent_visual_annotation_pilot.ipynb')
